        // Use vm.warp to control block.timestamp and vm.roll for block.difficulty.
        // First, set a specific block number so that keccak256 gives a value that is even.
        vm.warp(1);
        vm.roll(1);
        // First play
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.play{value: 10}();
        // After first win, in reference pot=0, in buggy pot=10 (since not reset).
        // Second play: need another block where random is even.
        // By changing block.timestamp to 3 and block.number to 3, keccak256(3,3) is likely even.
        vm.warp(3);
        vm.roll(3);
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.play{value: 10}();
        // After second win, reference: pot reset to 0 again. Buggy: pot = 20 (carried over from first).
        // So reference has c.pot() == 0, buggy has c.pot() == 20.
        assertTrue(c.pot() == 0, "pot expected 0");
    }
}

