pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address player = address(0x1234);
        vm.deal(player, 20);

        // First call: force random == 1 (non-zero) by setting block.timestamp and block.difficulty to produce odd hash
        vm.warp(1);
        vm.difficulty(2);
        // At warp 1, difficulty 2, keccak256(abi.encodePacked(1,2)) % 2 == 1 (non-zero)
        vm.prank(player);
        c.play{value: 10}();
        // Reference: random==1 => if(0) false => pot stays 10, no transfers
        // Bug: random==1 => if(1) true => pot reset, bank gets 1, player gets 9 => pot=0

        // Second call: force random == 0 by different block values
        vm.warp(2);
        vm.difficulty(1);
        // At warp 2, difficulty 1, keccak256(abi.encodePacked(2,1)) % 2 == 0
        vm.prank(player);
        c.play{value: 10}();
        // Reference: random==0 => if(0) true => pot reset, bank gets 1, player gets pot-1 (9 from accumulated 20) => pot=0
        // Bug: random==0 => if(1) false => pot accumulates: previous pot=0 + 10 = 10, no transfers => pot=10

        // After both calls, reference pot = 0, buggy pot = 10
        assertTrue(c.pot() == 0);
    }
}

