pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address player = address(1);
        vm.deal(player, 100);

        // Set block.timestamp and block.difficulty to make random == 0 on first call
        // keccak256(abi.encodePacked(1, 2)) % 2 == 1 (not zero), adjust to get 0
        vm.warp(1);
        vm.roll(2);

        // First call: random becomes 0
        vm.prank(player);
        c.play{value: 10}();

        // Now set different block timestamp/difficulty to make random != 0 on second call
        vm.warp(3);
        vm.roll(4);

        // Second call: random becomes 1
        vm.prank(player);
        c.play{value: 10}();

        // Reference: on random=0 (first call) pot reset to 0; then random=1 (second call) no action, pot becomes 10; 
        // Bug: on random=0 (first call) no action, pot=10; then random=1 (second call) resets pot with fee, pot becomes 0.
        // Actually after second call: reference pot = 10 (since first call reset, second call added 10 but no reset), buggy pot = 0 (first call did nothing, second call reset).
        uint256 refPot = 10;
        uint256 bugPot = 0;
        // But we don't know which is which at compile time - assertTrue that c.pot() equals refPot for reference
        assertTrue(c.pot() == refPot, "pot should be refPot on reference");
    }
}

