import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Warp to a block where keccak256 will produce a known non-zero random value (so first call loses)
        vm.warp(1);
        vm.roll(1);
        // First call: player sends 10 wei, random != 0 => pot stays 0 in buggy, becomes 10 in reference
        address player = address(0x1234);
        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10}();
        // After first call, reference pot = 10, buggy pot = 0
        // Warp to a different time so second call's random == 0 and will try to distribute
        vm.warp(2);
        vm.roll(2);
        address player2 = address(0x5678);
        vm.deal(player2, 10 ether);
        vm.prank(player2);
        // This call: if pot == 0, then pot - 1 underflows and reverts; if pot == 10, it succeeds
        bool ok;
        try c.play{value: 10}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the call succeeds (reference behavior). Buggy version would revert.
        assertTrue(ok);
    }
}

